EXPECTED = {"ep-canada": 75, "uocc": 284}
EXPECTED_TOTAL = 359
EXPECTED_CONTACT_ROWS = 271
EXPECTED_EMAILS = 181
EXPECTED_PHONES = 271
EXPECTED_SITES = 66
EXPECTED_KINDS = {"diocese": 43, "parish": 316, "monastery": 0}
ALLOWED_KINDS = {"diocese", "parish", "monastery"}
ALLOWED_RANKS = {
    "Administration", "Cathedral", "Cemetery Chapel", "Cemetery Church",
    "Chapel", "Church", "Community", "Eparchy", "Hermitage", "Mission",
    "Monastery", "Parish",
}
ALL_SOURCE_ROWS = [
    item for parent_rows in ROWS.values() for item in parent_rows
]
ENGLISH_NAMES = {item["id"]: item["name"] for item in ALL_SOURCE_ROWS}
ENGLISH_SEATS = {
    item["seat"]: item["seat"] for item in ALL_SOURCE_ROWS if item.get("seat")
}
CONTACTS = {
    item["id"]: {
        "emails": list(item.get("emails") or []),
        "phones": list(item.get("phones") or []),
        "contact_sources": list(item.get("contact_sources") or []),
    }
    for item in ALL_SOURCE_ROWS
}


def clean(source):
    item = {
        key: value for key, value in source.items()
        if value not in (None, "", [])
    }
    item.setdefault("checked", CHECKED)
    sources = list(item.get("sources") or [])
    if not sources or len(sources) > 3:
        raise ValueError("%s must cite one to three sources" % item.get("id"))
    if not all(urlparse(str(url)).scheme in {"http", "https"}
               and urlparse(str(url)).netloc for url in sources):
        raise ValueError("%s carries an invalid source" % item.get("id"))
    item["sources"] = sources
    item["cite"] = list(sources)
    return item


def validate_row(item, seen, branch_seen, names):
    row_id = item.get("id")
    if not row_id or row_id in seen:
        raise ValueError("duplicate or missing id: %s" % row_id)
    if not re.fullmatch(r"[a-z0-9-]+", row_id):
        raise ValueError("%s is not a stable ASCII id" % row_id)
    if item.get("parent") not in branch_seen:
        raise ValueError("%s hangs off an unknown parent: %s" % (
            row_id, item.get("parent"),
        ))
    if item.get("country") != "CA":
        raise ValueError("%s is outside Canada" % row_id)
    if item.get("kind") not in ALLOWED_KINDS:
        raise ValueError("%s has an unsupported kind" % row_id)
    if item.get("rank") not in ALLOWED_RANKS:
        raise ValueError("%s has an unsupported rank" % row_id)
    if not item.get("name") or not item.get("local"):
        raise ValueError("%s lacks a usable name" % row_id)
    name_key = item["name"].casefold()
    if name_key in names:
        raise ValueError("duplicate reader-facing name: %s and %s" % (
            names[name_key], row_id,
        ))
    names[name_key] = row_id
    for key in ("address", "emails", "phones", "contact_sources"):
        values = item.get(key)
        if values is not None and (
                not isinstance(values, list) or
                not all(isinstance(value, str) and value.strip()
                        for value in values)):
            raise ValueError("%s has invalid %s" % (row_id, key))
    for email in item.get("emails") or []:
        if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
            raise ValueError("%s has an invalid email" % row_id)
    contacts = bool(item.get("emails") or item.get("phones"))
    if contacts:
        if not item.get("contact_sources"):
            raise ValueError("%s has contacts without provenance" % row_id)
        if item.get("contact_checked") != CHECKED:
            raise ValueError("%s has an unsynchronized contact date" % row_id)
    elif item.get("contact_sources") or item.get("contact_checked"):
        raise ValueError("%s has orphan contact metadata" % row_id)
    for url in item.get("contact_sources") or []:
        parsed = urlparse(url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("%s has an invalid contact source" % row_id)
    if len(item.get("contact_sources") or []) > 3:
        raise ValueError("%s has too many contact sources" % row_id)
    if item.get("site"):
        parsed = urlparse(item["site"])
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("%s has an invalid body-owned site" % row_id)
    rendered = json.dumps(item, ensure_ascii=False)
    if any(mark in rendered for mark in (
            "\u2013", "\u2014", "\ufffd", "\u2018", "\u2019",
            "\u201c", "\u201d")):
        raise ValueError("%s has forbidden punctuation or encoding" % row_id)
    seen.add(row_id)
    branch_seen.add(row_id)


def build():
    payloads = {}
    seen = set(ROWS)
    names = {}
    kind_counts = {key: 0 for key in EXPECTED_KINDS}
    for parent, source_rows in ROWS.items():
        rows = []
        branch_seen = {parent}
        for source in source_rows:
            item = clean(source)
            validate_row(item, seen, branch_seen, names)
            kind_counts[item["kind"]] += 1
            rows.append(item)
        if len(rows) != EXPECTED[parent]:
            raise ValueError("%s count changed: %d" % (parent, len(rows)))
        payloads[parent] = {
            "v": 1,
            "parent": parent,
            "country": "CA",
            "rows": rows,
        }
    if sum(EXPECTED.values()) != EXPECTED_TOTAL:
        raise ValueError("Canada row total is out of sync")
    if kind_counts != EXPECTED_KINDS:
        raise ValueError("Canada kind counts are out of sync: %r" % kind_counts)
    if sum(bool(value["emails"] or value["phones"])
           for value in CONTACTS.values()) != EXPECTED_CONTACT_ROWS:
        raise ValueError("Canada contact-bearing row total is out of sync")
    if sum(len(value["emails"]) for value in CONTACTS.values()) != EXPECTED_EMAILS:
        raise ValueError("Canada email total is out of sync")
    if sum(len(value["phones"]) for value in CONTACTS.values()) != EXPECTED_PHONES:
        raise ValueError("Canada phone total is out of sync")
    if sum(bool(item.get("site")) for item in ALL_SOURCE_ROWS) != EXPECTED_SITES:
        raise ValueError("Canada body-owned site total is out of sync")
    return payloads


def validate_candidate_ledger():
    ledger = json.loads(CANDIDATE_LEDGER.read_text(encoding="utf-8"))
    if ledger.get("v") != 1 or ledger.get("country") != "CA":
        raise ValueError("Canada candidate ledger has the wrong schema or country")
    if ledger.get("checked") != CHECKED:
        raise ValueError("Canada candidate ledger date is out of sync")
    expected_summary = {
        "greek_archdiocese": 75,
        "uocc_eparchies": 3,
        "uocc_regions": 40,
        "uocc_parishes": 241,
        "total": EXPECTED_TOTAL,
        "canonical_jurisdictions_represented": 2,
    }
    if ledger.get("published_summary") != expected_summary:
        raise ValueError("Canada candidate ledger totals are out of sync")
    required_lists = (
        "candidates", "reconciliation", "official_jurisdiction_audit",
        "limitations",
    )
    for key in required_lists:
        if not isinstance(ledger.get(key), list) or not ledger[key]:
            raise ValueError("Canada candidate ledger lacks %s" % key)
        for item in ledger[key]:
            sources = item.get("sources") or []
            if not sources or len(sources) > 3:
                raise ValueError("Canada ledger item must cite one to three sources")
            if not all(urlparse(str(url)).scheme in {"http", "https"}
                       and urlparse(str(url)).netloc for url in sources):
                raise ValueError("Canada ledger item carries an invalid source")
    candidate_ids = [item.get("candidate_id") for item in ledger["candidates"]]
    if any(not value or not re.fullmatch(r"[a-z0-9-]+", value)
           for value in candidate_ids):
        raise ValueError("Canada candidate ledger carries an invalid id")
    if len(candidate_ids) != len(set(candidate_ids)):
        raise ValueError("Canada candidate ledger has duplicate ids")
    rendered = json.dumps(ledger, ensure_ascii=False)
    if any(mark in rendered for mark in (
            "\u2013", "\u2014", "\ufffd", "\u2018", "\u2019",
            "\u201c", "\u201d")):
        raise ValueError("Canada candidate ledger has forbidden punctuation")
    return ledger


def main():
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--dump", action="store_true")
    args = parser.parse_args()
    try:
        payloads = build()
        validate_candidate_ledger()
    except (OSError, ValueError) as exc:
        print("directory Canada: %s" % exc, file=sys.stderr)
        return 1
    if args.dump:
        print(json.dumps(payloads, ensure_ascii=False, indent=2,
                         sort_keys=True))
    else:
        print(
            "Canada tranche: 359 current official rows across "
            "2 canonical jurisdictions"
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
